# Write data/catastrophe_events.csv
keys = events[0].keys()
with open('data/catastrophe_events.csv', 'w', newline='', encoding='utf-8') as f:
    dict_writer = csv.DictWriter(f, fieldnames=keys)
    dict_writer.writeheader()
    dict_writer.writerows(events)

# Copy to public for direct web download in browser
with open('public/catastrophe_events.csv', 'w', newline='', encoding='utf-8') as f:
    dict_writer = csv.DictWriter(f, fieldnames=keys)
    dict_writer.writeheader()
    dict_writer.writerows(events)

print(f"Generated data/catastrophe_events.csv and public/catastrophe_events.csv with {len(events)} events.")
